CREATE SCHEMA IF NOT EXISTS clickup;
CREATE TABLE IF NOT EXISTS clickup.tasks (
  id TEXT PRIMARY KEY, name TEXT, name_khong_dau TEXT, url TEXT, description TEXT,
  status TEXT, phu_trach TEXT, dkpv TEXT, pvtc TEXT, folder_name TEXT, list_name TEXT,
  vfs TEXT, planbay TEXT, ngaybay TEXT, youtube_link TEXT, onedrive_link TEXT, color TEXT,
  other_link TEXT, date_updated TIMESTAMPTZ, synced_at TIMESTAMPTZ DEFAULT now()
);

